// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    ReentrancyDAO c;
    function setUp() public { c = new ReentrancyDAO(); }

    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(amount <= VALUE_CAP);
        // Admissible domain: actor must be a plain recipient (no code, not the
        // test contract, not c itself) so the low-level ETH transfer always
        // succeeds; amount must be a positive, fundable deposit.
        vm.assume(actor.code.length == 0);
        vm.assume(actor != address(c));
        vm.assume(actor != address(this));
        vm.assume(actor != address(0));
        amount = bound(amount, 1, 100 ether);

        // Deposit by the fuzzer-chosen actor.
        vm.deal(actor, amount);
        vm.prank(actor);
        c.deposit{value: amount}();

        // First withdrawal must succeed for any admissible input.
        vm.prank(actor);
        bool ok1;
        try c.withdrawAll() { ok1 = true; } catch { ok1 = false; }
        require(ok1, "first withdrawal failed on admissible input");

        // Rule: the first withdrawal consumes the caller's credit, so a second
        // withdrawAll is a no-op that MUST succeed without reverting.
        vm.prank(actor);
        bool ok2;
        try c.withdrawAll() { ok2 = true; } catch { ok2 = false; }
        assertTrue(ok2, "second withdrawAll must be a harmless no-op");
    }
}
